"""Framework-owned package byte encoding; portable copies are generated by Framework."""
from __future__ import annotations

import hashlib
from pathlib import Path
from typing import Callable, Iterable


def content_digest(paths: Iterable[str], read_bytes: Callable[[str], bytes]) -> str:
    digest = hashlib.sha256()
    for relative in paths:
        body = read_bytes(relative)
        encoded = relative.encode("utf-8")
        digest.update(len(encoded).to_bytes(8, "big"))
        digest.update(encoded)
        digest.update(len(body).to_bytes(8, "big"))
        digest.update(body)
    return f"sha256:{digest.hexdigest()}"


def content_lock(root: Path, paths: list[str]) -> dict[str, object]:
    return {
        "algorithm": "sha256",
        "canonicalization": "ordered_path_length_file_length_bytes",
        "paths": paths,
        "digest": content_digest(paths, lambda relative: (root / relative).read_bytes()),
    }
